// das nav-Element
const worksNav = document.querySelector(".works-nav");

// der Button mit der ID "naviButton"
const worksButton = document.querySelector(".works-button");

//nav menu sichtbar machen
if (worksButton && worksNav) {
  worksButton.addEventListener("click", function (event) {
    worksNav.classList.toggle("sichtbar");

    event.stopPropagation();
  });

  // nav schließen wenn: click woanders hin
  document.addEventListener("click", function (event) {
    // prüft ob click woanders ist
    if (
      !worksNav.contains(event.target) &&
      !worksButton.contains(event.target)
    ) {
      worksNav.classList.remove("sichtbar");
    }
  });
}

// td wird blocksatz unter th wenn es über mehrere zeilen geht
function updateWrappedTds() {
  document.querySelectorAll("table").forEach((table) => {
    table.querySelectorAll("tr").forEach((tr) => {
      const th = tr.querySelector("th");
      const td = tr.querySelector("td");
      if (!th || !td) return;
      const thRect = th.getBoundingClientRect();
      const tdRect = td.getBoundingClientRect();
      if (tdRect.top > thRect.top + 2 || tdRect.height > thRect.height + 2) {
        td.style.textAlign = "justify";
        td.classList.add("wrapped-below");
        td.style.paddingTop = 0;
      } else {
        td.style.textAlign = "right";
        td.style.padding = "";
        td.classList.remove("wrapped-below");
      }
    });
  });
}

// Projektbeschreibungstabelle bei breiter Bildschirmbreite scrollbar machen, wenn Bildschirm zu wenig hoch ist, um alles anzuzeigen
let __wrapResizeTimer;
// table max height so gesetzt dass unterer rand immer im bildschirm ist
function adjustTablesMaxHeight(paddingBottom = 12) {
  document.querySelectorAll("table").forEach((table) => {
    const rect = table.getBoundingClientRect();
    const available = Math.max(
      50,
      window.innerHeight - rect.top - paddingBottom,
    );
    table.style.maxHeight = available + "px";
  });
}
//nur bei großer version, nicht bei der kleineren version durch media query
function isInfoKleinActive() {
  return window.matchMedia("(max-width: 1000px)").matches;
}

window.addEventListener("load", function () {
  updateWrappedTds();
  if (!isInfoKleinActive()) adjustTablesMaxHeight();
  else
    document.querySelectorAll("table").forEach((t) => (t.style.maxHeight = ""));
});

window.addEventListener("resize", function () {
  clearTimeout(__wrapResizeTimer);
  __wrapResizeTimer = setTimeout(function () {
    updateWrappedTds();
    if (!isInfoKleinActive()) adjustTablesMaxHeight();
    else
      document
        .querySelectorAll("table")
        .forEach((t) => (t.style.maxHeight = ""));
  }, 120);
});
// also run after fonts load (if available)
if (document.fonts && document.fonts.ready)
  document.fonts.ready.then(function () {
    updateWrappedTds();
    if (!isInfoKleinActive()) adjustTablesMaxHeight();
    else
      document
        .querySelectorAll("table")
        .forEach((t) => (t.style.maxHeight = ""));
  });
